const COLLEGES=['哲学与社会发展学院','经济学院','文学院','历史学院','考古学院','数学学院','物理学院','化学与化工学院','管理学院','马克思主义学院','国际教育学院','新闻传播学院','外国语学院','艺术学院','基础医学院','公共卫生学院','口腔医学院','护理与康复学院','药学院','材料科学与工程学院','机械工程学院','控制科学与工程学院','核科学与能源动力学院','电气工程学院','土建与水利学院','体育学院','软件学院','集成电路学院','密码科学与工程学院','人工智能学院','政治学与公共管理学院','法学院','信息科学与工程学院','计算机科学与技术学院','生命科学学院','环境科学与工程学院','网络空间安全学院'];
const SKEY='bianyu-demo-v1';let saved;try{saved=JSON.parse(localStorage.getItem(SKEY)||'{}')}catch{saved={}}let state={dust:80,ink:20,xp:0,college:'',deck:['b0','b0','b1','b2','b3','b3','b4','b5','b6','b7','b8','b9','b10','b11','b12'],custom:[],...saved};let game,selectedCard=null,filter='all',editing=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const cards=()=>[...BASE,...state.custom];const byId=id=>cards().find(c=>c.id===id);function save(){localStorage.setItem(SKEY,JSON.stringify(state));renderProfile()}function toast(t){let el=$('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',2600)}
function go(page){$$('.page').forEach(x=>x.classList.toggle('active',x.id===page));$$('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#breadcrumb').textContent='校队世界 / '+({home:'探索首页',battle:'卡牌对战',collection:'卡牌工坊',rules:'游戏规则书',team:'校队正赛',developer:'开发者入口'}[page]);if(page==='battle')renderGame();if(page==='collection')renderCollection();if(page==='developer')renderCustom();window.scrollTo(0,0)}$$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
function renderProfile(){let level=1+Math.floor(state.xp/100);$('#dust').textContent=state.dust;$('#ink').textContent=state.ink;$('#collegeName').textContent=state.college||'尚未选择学院';$('#collegeIcon').textContent=(state.college||'山')[0];$('#profileBtn').textContent=(state.college||'山')[0];$('#xpbar').style.width=(state.xp%100)+'%';$('#xptext').textContent=`账号等级 ${level} · ${state.xp%100}/100 成长经验`}
$('#collegeGrid').innerHTML=COLLEGES.map(c=>`<button type="button" data-college="${esc(c)}">${esc(c)}</button>`).join('');$$('[data-college]').forEach(b=>b.onclick=()=>{state.college=b.dataset.college;save();$('#collegeDialog').close();toast('学院身份已选择')});$('#profileBtn').onclick=$('#collegeBtn').onclick=()=>$('#collegeDialog').showModal();
function effectText(c){return ({plain:'基础影响力',late:'第 5、6 轮打出时 +2',draw:'打出时抽 1 张',move:'打出时可移动己方一张卡',support:'同阵地另一张己方卡 +1',final:'第 6 轮打出时 +2',comeback:'落后阵地打出时 +2',partner:'同阵地已有己方人物卡时 +2',shift:'移动己方一张人物卡',boost:'己方一张人物卡 +1',double:'本阵地两张己方人物卡各 +1',weaken2:'对方一张人物卡 -2',laneBoost:'落后阵地己方总影响力 +3',swap:'交换己方两个阵地的人物卡',prep:'抽 2 张；本轮下一张人物卡费用 -1',allBoost:'每个阵地的一张己方人物卡 +2',weaken:'对方一张人物卡 -1'}[c.effect]||'基础影响力')}
function cardHTML(c,extra=''){return `<span class="card-top"><span>${c.type==='unit'?'人物':'事件'}</span><b>◆ ${c.cost}</b></span><strong>${esc(c.name)}</strong><p>${esc(effectText(c))}</p><span class="card-bottom">${c.type==='unit'?'✦ '+c.power+' 影响力':'✧ 即时效果'}${c.id.startsWith('c')?' · 原创':''}</span>`}
function renderCollection(){let list=cards().filter(c=>filter==='all'||(filter==='custom'?c.id.startsWith('c'):c.type===filter));$('#deckCount').textContent=state.deck.length;$('#cardGrid').innerHTML=list.map(c=>`<button class="game-card ${c.type==='event'?'event':''} ${state.deck.includes(c.id)?'in-deck':''}" data-id="${c.id}">${cardHTML(c)}<small>卡组中 ${state.deck.filter(x=>x===c.id).length}/2</small></button>`).join('');$$('#cardGrid button').forEach(b=>b.onclick=()=>{let id=b.dataset.id,n=state.deck.filter(x=>x===id).length;if(n===0){if(state.deck.length>=15)return toast('卡组已满，先移出一张');state.deck.push(id)}else if(n===1&&state.deck.length<15){state.deck.push(id)}else{state.deck.splice(state.deck.indexOf(id),1)}save();renderCollection()})}$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderCollection()});$('#resetDeck').onclick=()=>{state.deck=['b0','b0','b1','b2','b3','b3','b4','b5','b6','b7','b8','b9','b10','b11','b12'];save();renderCollection();toast('已恢复初始卡组')};
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}function draw(side,n=1){for(let i=0;i<n;i++)if(game[side].deck.length)game[side].hand.push(game[side].deck.pop())}function power(side,lane){return game[side].lanes[lane].reduce((n,c)=>n+c.power,0)+game[side].bonus[lane]}function log(t){game.logs.unshift(t);game.logs=game.logs.slice(0,14)}function newGame(){let chosen=state.deck.length===15?state.deck:['b0','b0','b1','b2','b3','b3','b4','b5','b6','b7','b8','b9','b10','b11','b12'];game={round:1,energy:3,done:false,player:{deck:shuffle(chosen),hand:[],lanes:[[],[],[]],bonus:[0,0,0],discount:0},enemy:{deck:shuffle(['b0','b0','b1','b2','b3','b3','b4','b5','b6','b7','b8','b9','b10','b11','b12']),hand:[],lanes:[[],[],[]],bonus:[0,0,0],discount:0},logs:[]};draw('player',4);draw('enemy',4);selectedCard=null;log('对局开始。请选择手牌与阵地。');renderGame()}
function first(arr){return arr.length?arr[0]:null}function applyEffect(side,lane,c,unit){let own=game[side],opp=game[side==='player'?'enemy':'player'],here=own.lanes[lane],foe=opp.lanes[lane];switch(c.effect){case 'late':if(game.round>=5)unit.power+=2;break;case 'final':if(game.round===6)unit.power+=2;break;case 'comeback':if(power(side,lane)<power(side==='player'?'enemy':'player',lane))unit.power+=2;break;case 'partner':if(here.length>1)unit.power+=2;break;case 'draw':draw(side);break;case 'support':{let other=here.find(x=>x!==unit);if(other)other.power++;break}case 'move':case 'shift':{let from=own.lanes.findIndex((arr,i)=>i!==lane&&arr.length&&here.length<2);if(from>=0)here.push(own.lanes[from].pop());break}case 'boost':if(first(here))first(here).power++;break;case 'double':here.forEach(x=>x.power++);break;case 'weaken':if(first(foe))first(foe).power=Math.max(0,first(foe).power-1);break;case 'weaken2':if(first(foe))first(foe).power=Math.max(0,first(foe).power-2);break;case 'laneBoost':if(power(side,lane)<power(side==='player'?'enemy':'player',lane))own.bonus[lane]+=3;break;case 'swap':{let other=own.lanes.findIndex((arr,i)=>i!==lane&&arr.length);if(other>=0&&here.length){let x=here[0];here[0]=own.lanes[other][0];own.lanes[other][0]=x}break}case 'prep':draw(side,2);own.discount=1;break;case 'allBoost':own.lanes.forEach(arr=>{if(arr[0])arr[0].power+=2});break}}
function play(side,index,lane){let s=game[side],c=byId(s.hand[index]);if(!c)return false;let cost=Math.max(0,c.cost-(c.type==='unit'?s.discount:0));if(cost>game.energy||(c.type==='unit'&&s.lanes[lane].length>=2))return false;game.energy-=cost;s.hand.splice(index,1);if(c.type==='unit')s.discount=0;let unit=c.type==='unit'?{name:c.name,power:c.power}:null;if(unit)s.lanes[lane].push(unit);applyEffect(side,lane,c,unit);log(`${side==='player'?'你':'对手'}在「${['起点','交锋','终局'][lane]}」打出 ${c.name}`);return true}
function finish(){game.done=true;let p=0,e=0;for(let i=0;i<3;i++){if(power('player',i)>power('enemy',i))p++;else if(power('enemy',i)>power('player',i))e++}let sum=s=>[0,1,2].reduce((n,i)=>n+power(s,i),0);let result=p>e||p===e&&sum('player')>sum('enemy')?'胜利':e>p||p===e&&sum('enemy')>sum('player')?'惜败':'平局';let reward=result==='胜利'?{dust:18,ink:8,xp:30}:{dust:10,ink:5,xp:18};state.dust+=reward.dust;state.ink+=reward.ink;state.xp+=reward.xp;save();log(`对局结束：${result}。获得 ${reward.dust} 灵感、${reward.ink} 墨迹。`);toast(`${result}！奖励已存入账号`)}function enemyTurn(){game.energy=3;let tries=0;while(tries++<5){let options=game.enemy.hand.map((id,i)=>({i,c:byId(id)})).filter(x=>x.c&&x.c.cost<=game.energy);if(!options.length)break;let choice=options.sort((a,b)=>b.c.cost-a.c.cost)[0],lanes=[0,1,2].filter(i=>choice.c.type==='event'||game.enemy.lanes[i].length<2);if(!lanes.length)break;lanes.sort((a,b)=>(power('player',b)-power('enemy',b))-(power('player',a)-power('enemy',a)));if(!play('enemy',choice.i,lanes[0]))break}if(game.round===6){finish()}else{game.round++;game.energy=3;game.player.discount=0;game.enemy.discount=0;draw('player');draw('enemy');log(`第 ${game.round} 轮开始`)}renderGame()}
function renderGame(){if(!game)newGame();$('#roundText').textContent=`第 ${game.round} / 6 轮`;$('#energyText').textContent=game.done?'—':`${game.energy} / 3`;$('#turnText').textContent=game.done?'已结束':'你';$('#endTurn').disabled=game.done;$('#battleHint').textContent=game.done?'对局结束，点击重新开局再玩一次。':selectedCard===null?'选择一张手牌，再选择要打出的阵地。':'已选中手牌，点击一个阵地打出。';$('#lanes').innerHTML=[0,1,2].map(i=>`<div class="lane" data-lane="${i}"><div class="lane-title"><span>${['起点','交锋','终局'][i]}</span><span class="lane-score">${power('enemy',i)} : ${power('player',i)}</span></div><div class="slots">${[0,1].map(n=>game.enemy.lanes[i][n]?`<div class="mini-card enemy"><b>${esc(game.enemy.lanes[i][n].name)}</b><span>✦ ${game.enemy.lanes[i][n].power}</span></div>`:'<div class="slot">对手空位</div>').join('')}</div><div class="divider">VS</div><div class="slots">${[0,1].map(n=>game.player.lanes[i][n]?`<div class="mini-card"><b>${esc(game.player.lanes[i][n].name)}</b><span>✦ ${game.player.lanes[i][n].power}</span></div>`:'<div class="slot">你的空位</div>').join('')}</div></div>`).join('');$$('.lane').forEach(el=>el.onclick=()=>{if(game.done||selectedCard===null)return;let c=byId(game.player.hand[selectedCard]);if(!c)return;if(!play('player',selectedCard,Number(el.dataset.lane)))return toast('行动力不足，或人物卡位置已满');selectedCard=null;renderGame()});$('#hand').innerHTML=game.player.hand.map((id,i)=>{let c=byId(id);return c?`<button class="game-card ${c.type==='event'?'event':''} ${selectedCard===i?'selected':''}" data-index="${i}">${cardHTML(c)}</button>`:''}).join('');$$('#hand button').forEach(b=>b.onclick=()=>{selectedCard=Number(b.dataset.index);renderGame()});$('#battleLog').innerHTML=game.logs.map(x=>`<div>${esc(x)}</div>`).join('')}$('#newGame').onclick=newGame;$('#endTurn').onclick=()=>{if(game.done)return;selectedCard=null;enemyTurn()};
function renderCustom(){let list=state.custom;$('#customList').innerHTML=list.length?list.map(c=>`<div class="custom-item"><div><strong>${esc(c.name)}</strong><br><span>${c.type==='unit'?'人物':'事件'} · 费用 ${c.cost}</span></div><div><button data-edit="${c.id}">编辑</button><button data-delete="${c.id}">删除</button></div></div>`).join(''):'<p>还没有原创卡。先设计第一张吧。</p>';$$('[data-edit]').forEach(b=>b.onclick=()=>{let c=byId(b.dataset.edit);editing=c.id;$('#editName').value=c.name;$('#editType').value=c.type;$('#editCost').value=c.cost;$('#editPower').value=c.power;$('#editEffect').value=c.effect;$('#editLore').value=c.lore;$('#powerWrap').style.display=c.type==='unit'?'grid':'none';window.scrollTo(0,0)});$$('[data-delete]').forEach(b=>b.onclick=()=>{let id=b.dataset.delete;state.custom=state.custom.filter(c=>c.id!==id);state.deck=state.deck.filter(x=>x!==id);save();renderCustom();toast('原创卡已删除')})}$('#editType').onchange=()=>$('#powerWrap').style.display=$('#editType').value==='unit'?'grid':'none';function clearForm(){editing=null;$('#cardForm').reset();$('#powerWrap').style.display='grid'}$('#clearForm').onclick=clearForm;$('#cardForm').onsubmit=e=>{e.preventDefault();let c={id:editing||'c'+Date.now(),name:$('#editName').value.trim(),type:$('#editType').value,cost:Number($('#editCost').value),power:$('#editType').value==='unit'?Number($('#editPower').value):0,effect:$('#editEffect').value,lore:$('#editLore').value.trim()};if(!c.name||c.cost<1||c.cost>3||c.power<0||c.power>8)return toast('请检查卡牌数值');if(editing)state.custom=state.custom.map(x=>x.id===editing?c:x);else state.custom.push(c);save();renderCustom();clearForm();toast('卡牌已保存，可在卡牌工坊中组卡')};$('#exportCards').onclick=()=>{let blob=new Blob([JSON.stringify({format:'bianyu-cards-v1',cards:state.custom},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='辩域原创卡.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#importCards').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{let data=JSON.parse(await file.text());if(data.format!=='bianyu-cards-v1'||!Array.isArray(data.cards))throw Error();let valid=data.cards.filter(c=>c&&typeof c.name==='string'&&c.name.length<=18&&['unit','event'].includes(c.type)&&Number.isInteger(c.cost)&&c.cost>=1&&c.cost<=3&&Number.isInteger(c.power)&&c.power>=0&&c.power<=8&&typeof c.lore==='string'&&c.lore.length<=120&&['plain','draw','boost','weaken','comeback'].includes(c.effect)).slice(0,100).map((c,i)=>({...c,id:'c'+Date.now()+i}));state.custom.push(...valid);save();renderCustom();toast(`已导入 ${valid.length} 张卡牌`)}catch{toast('文件格式不正确')}e.target.value=''};
renderProfile();renderCollection();renderCustom();newGame();if(!state.college)setTimeout(()=>$('#collegeDialog').showModal(),450);
